// 메인 패널을 LAN(박물관 PC 자체 또는 같은 네트워크)에서 보고 있으면
// cloudflared 터널이 끊겨도 localhost:5556 으로 직접 접근하여 CCTV가 끊기지 않게 함
const DEFAULT_CCTV_SERVER_URL = (() => {
  try {
    if (typeof window !== "undefined" && window.location) {
      const h = window.location.hostname;
      if (h === "localhost" || h === "127.0.0.1" ||
          h.startsWith("192.168.") || h.startsWith("10.") ||
          /^172\.(1[6-9]|2[0-9]|3[0-1])\./.test(h)) {
        return "http://localhost:5556";
      }
    }
  } catch (e) {}
  return "https://cctv.thejamsa.com";
})();
const DEFAULT_OKPOS_BRIDGE_URL = "http://127.0.0.1:5566";
const JAMSA_PROTECTED_KEYS = [
  "jamsa_inv_prods",
  "jamsa_inv_hist",
  "jamsa_worklogs",
  "jamsa_worklog_active_checks",
  "jamsa_worklog_staff",
  "jamsa_incidents",
  "jamsa_daily_checks",
  "jamsa_audit_log",
  "jamsa_fac_actions",
  "jamsa_fac_inspections",
  "jamsa_custom_zones",
  "jamsa_zone_photos",
  "jamsa_zonePhotos",
  "jamsa_warehouse_models",
  "jamsa_storage_sections",
  "jamsa_locations",
  "jamsa_categories",
  "jamsa_requisitions",
  "jamsa_payments",
  "jamsa_cctv_snap_server",
  "jamsa_cctv_zone_map",
  "jamsa_cctv_offsets",
  "jamsa_cctv_guard_url",
];
const JAMSA_PROTECTION_SNAPSHOTS_KEY = "jamsa_data_protection_snapshots";
const JAMSA_PROTECTION_LAST_GOOD_KEY = "jamsa_data_protection_last_good";
const JAMSA_OKPOS_EVENTS_KEY = "jamsa_okpos_usage_events";

const getOkposBridgeUrl = () => {
  try {
    return (window.localStorage.getItem("jamsa_okpos_bridge_url") || DEFAULT_OKPOS_BRIDGE_URL).replace(/\/+$/, "");
  } catch (e) {
    return DEFAULT_OKPOS_BRIDGE_URL;
  }
};

async function forwardOnlineUsageToOkpos(payload) {
  const event = {
    id: payload?.id || `usage-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    source: payload?.source || "jamsa-panel",
    type: payload?.type || "online_usage",
    createdAt: new Date().toISOString(),
    ...payload,
  };
  try {
    const bridgeUrl = getOkposBridgeUrl();
    const res = await fetch(`${bridgeUrl}/okpos/usage`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(event),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || data.ok === false) throw new Error(data.message || `HTTP ${res.status}`);
    return { ok: true, bridge: data };
  } catch (e) {
    try {
      const current = JSON.parse(window.localStorage.getItem(JAMSA_OKPOS_EVENTS_KEY) || "[]");
      current.unshift({ ...event, status: "pending_local_bridge", error: e.message || String(e) });
      window.localStorage.setItem(JAMSA_OKPOS_EVENTS_KEY, JSON.stringify(current.slice(0, 500)));
    } catch (storageError) {}
    return { ok: false, error: e.message || String(e), queued: true };
  }
}

const rawLocalStorageGet = (key) => {
  const nativeGet = window.__jamsaNativeLocalStorageGetItem || Storage.prototype.getItem;
  return nativeGet.call(window.localStorage, key);
};

const getStorageRaw = (key) => {
  try { return rawLocalStorageGet(key); } catch (e) { return null; }
};

const rawLocalStorageSet = (key, value) => {
  const nativeSet = window.__jamsaNativeLocalStorageSetItem || Storage.prototype.setItem;
  nativeSet.call(window.localStorage, key, value);
};

const queueCloudStorageSync = (key, rawValue) => {
  try {
    if (typeof window === "undefined" || !String(key).startsWith("jamsa_")) return;
    if (typeof window.__jamsaQueueCloudSync === "function") {
      window.__jamsaQueueCloudSync(String(key), rawValue);
      return;
    }
    window.dispatchEvent(new CustomEvent("jamsa:storage-sync", { detail: { key: String(key), value: rawValue } }));
  } catch (e) {}
};

const rawLocalStorageClear = () => {
  const nativeClear = window.__jamsaNativeLocalStorageClear || Storage.prototype.clear;
  nativeClear.call(window.localStorage);
};

const parseStorageValue = (raw) => {
  if (raw == null || raw === "") return null;
  try { return JSON.parse(raw); } catch (e) { return raw; }
};

const protectedValueCount = (value) => {
  if (Array.isArray(value)) return value.length;
  if (value && typeof value === "object") return Object.keys(value).length;
  if (typeof value === "string") return value.trim() ? 1 : 0;
  return value == null ? 0 : 1;
};

const protectedValueIsEmpty = (value) => protectedValueCount(value) === 0;

const serializeStorageValue = (value) => (typeof value === "string" ? value : JSON.stringify(value));

const collectProtectedData = () => {
  const data = {};
  JAMSA_PROTECTED_KEYS.forEach(key => {
    const raw = getStorageRaw(key);
    if (raw == null) return;
    const value = parseStorageValue(raw);
    if (!protectedValueIsEmpty(value)) data[key] = value;
  });
  return data;
};

const summarizeProtectedData = (data) => {
  const summary = {};
  Object.entries(data || {}).forEach(([key, value]) => { summary[key] = protectedValueCount(value); });
  return summary;
};

const fingerprintProtectedData = (data) => {
  try { return JSON.stringify(summarizeProtectedData(data)); } catch (e) { return String(Date.now()); }
};

const saveDataProtectionSnapshot = (reason = "manual", opts = {}) => {
  try {
    if (typeof window === "undefined" || !window.localStorage) return null;
    const data = opts.data || collectProtectedData();
    if (!Object.keys(data).length) return null;
    const snap = {
      id: `safe_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      at: new Date().toISOString(),
      reason,
      summary: summarizeProtectedData(data),
      data,
    };
    const prev = parseStorageValue(getStorageRaw(JAMSA_PROTECTION_SNAPSHOTS_KEY)) || [];
    const last = Array.isArray(prev) ? prev[0] : null;
    if (!opts.force && last?.fingerprint === fingerprintProtectedData(data)) return last;
    snap.fingerprint = fingerprintProtectedData(data);
    rawLocalStorageSet(JAMSA_PROTECTION_SNAPSHOTS_KEY, JSON.stringify([snap, ...(Array.isArray(prev) ? prev : [])].slice(0, 20)));
    rawLocalStorageSet(JAMSA_PROTECTION_LAST_GOOD_KEY, JSON.stringify({ at: snap.at, summary: snap.summary, data }));
    window.sessionStorage?.setItem("jamsa_data_last_snapshot_notice", `${reason} · ${Object.keys(data).length}개 데이터 보호`);
    return snap;
  } catch (e) {
    console.warn("[data protection] snapshot failed:", e.message);
    return null;
  }
};

const guardedLocalStorageSet = (key, value) => {
  const raw = serializeStorageValue(value);
  if (!JAMSA_PROTECTED_KEYS.includes(key)) {
    rawLocalStorageSet(key, raw);
    queueCloudStorageSync(key, raw);
    return true;
  }
  const before = parseStorageValue(getStorageRaw(key));
  const beforeCount = protectedValueCount(before);
  const nextCount = protectedValueCount(value);
  if (beforeCount > 0 && nextCount === 0) {
    saveDataProtectionSnapshot(`blocked-empty-overwrite:${key}`, { force: true });
    console.warn(`[data protection] blocked empty overwrite for ${key}`);
    return false;
  }
  rawLocalStorageSet(key, raw);
  queueCloudStorageSync(key, raw);
  const lastGood = parseStorageValue(getStorageRaw(JAMSA_PROTECTION_LAST_GOOD_KEY)) || { data: {} };
  if (nextCount > 0) {
    lastGood.data = { ...(lastGood.data || {}), [key]: value };
    lastGood.at = new Date().toISOString();
    lastGood.summary = summarizeProtectedData(lastGood.data);
    rawLocalStorageSet(JAMSA_PROTECTION_LAST_GOOD_KEY, JSON.stringify(lastGood));
  }
  return true;
};

const restoreMissingProtectedData = () => {
  try {
    const clearRequestedAt = Number(getStorageRaw("jamsa_data_clear_requested_at") || 0);
    if (clearRequestedAt && Date.now() - clearRequestedAt < 10 * 60 * 1000) return [];
    const lastGood = parseStorageValue(getStorageRaw(JAMSA_PROTECTION_LAST_GOOD_KEY));
    if (!lastGood?.data) return [];
    const restored = [];
    JAMSA_PROTECTED_KEYS.forEach(key => {
      const current = parseStorageValue(getStorageRaw(key));
      const backup = lastGood.data[key];
      if (protectedValueIsEmpty(current) && !protectedValueIsEmpty(backup)) {
        const rawBackup = serializeStorageValue(backup);
        rawLocalStorageSet(key, rawBackup);
        queueCloudStorageSync(key, rawBackup);
        restored.push(key);
      }
    });
    if (restored.length) {
      window.sessionStorage?.setItem("jamsa_data_auto_restored", restored.join(","));
      saveDataProtectionSnapshot("after-auto-restore", { force: true });
    }
    return restored;
  } catch (e) {
    console.warn("[data protection] auto restore failed:", e.message);
    return [];
  }
};

const installDataProtectionGuards = () => {
  try {
    if (typeof window === "undefined" || window.__jamsaDataProtectionInstalled) return;
    window.__jamsaDataProtectionInstalled = true;
    if (!window.__jamsaNativeLocalStorageGetItem) {
      window.__jamsaNativeLocalStorageGetItem = Storage.prototype.getItem;
    }
    if (!window.__jamsaNativeLocalStorageSetItem) {
      window.__jamsaNativeLocalStorageSetItem = Storage.prototype.setItem;
      Storage.prototype.setItem = function(key, value) {
        if (this === window.localStorage && JAMSA_PROTECTED_KEYS.includes(String(key))) {
          const parsed = parseStorageValue(String(value));
          guardedLocalStorageSet(String(key), parsed);
          return;
        }
        window.__jamsaNativeLocalStorageSetItem.call(this, key, value);
      };
    }
    if (!window.__jamsaNativeLocalStorageRemoveItem) {
      window.__jamsaNativeLocalStorageRemoveItem = Storage.prototype.removeItem;
      Storage.prototype.removeItem = function(key) {
        if (this === window.localStorage && JAMSA_PROTECTED_KEYS.includes(String(key))) {
          saveDataProtectionSnapshot(`before-remove:${String(key)}`, { force: true });
        }
        window.__jamsaNativeLocalStorageRemoveItem.call(this, key);
      };
    }
    if (!window.__jamsaNativeLocalStorageClear) {
      window.__jamsaNativeLocalStorageClear = Storage.prototype.clear;
      Storage.prototype.clear = function() {
        if (this !== window.localStorage) {
          window.__jamsaNativeLocalStorageClear.call(this);
          return;
        }
        const previousLastGood = parseStorageValue(getStorageRaw(JAMSA_PROTECTION_LAST_GOOD_KEY));
        const snap = saveDataProtectionSnapshot("before-storage-clear", { force: true });
        const mergedData = { ...(previousLastGood?.data || {}), ...(snap?.data || {}) };
        rawLocalStorageClear();
        if (Object.keys(mergedData).length) {
          const mergedSnap = snap ? { ...snap, data: mergedData, summary: summarizeProtectedData(mergedData) } : {
            id: `safe_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
            at: new Date().toISOString(),
            reason: "before-storage-clear",
            data: mergedData,
            summary: summarizeProtectedData(mergedData),
          };
          rawLocalStorageSet(JAMSA_PROTECTION_SNAPSHOTS_KEY, JSON.stringify([mergedSnap]));
          rawLocalStorageSet(JAMSA_PROTECTION_LAST_GOOD_KEY, JSON.stringify({ at: mergedSnap.at, summary: mergedSnap.summary, data: mergedData }));
        }
      };
    }
    restoreMissingProtectedData();
    saveDataProtectionSnapshot("app-load");
    window.__jamsaDataProtection = {
      snapshot: (reason = "manual-console") => saveDataProtectionSnapshot(reason, { force: true }),
      restoreMissing: restoreMissingProtectedData,
      keys: JAMSA_PROTECTED_KEYS,
    };
    setInterval(() => saveDataProtectionSnapshot("interval-5min"), 5 * 60 * 1000);
    window.addEventListener("beforeunload", () => saveDataProtectionSnapshot("before-unload"));
    window.addEventListener("storage", e => {
      if (e?.key && JAMSA_PROTECTED_KEYS.includes(e.key)) setTimeout(restoreMissingProtectedData, 50);
    });
  } catch (e) {
    console.warn("[data protection] install failed:", e.message);
  }
};

// CCTV backend bootstrap: use one default cloud endpoint everywhere.
try {
  if (typeof window !== 'undefined' && window.localStorage) {
    try { rawLocalStorageSet("jamsa_cctv_snap_server", DEFAULT_CCTV_SERVER_URL); } catch (e) {}
    installDataProtectionGuards();
  }
} catch(e) {}
/* ─── LOCAL STORAGE PERSISTENCE HOOK ───
   Drop-in replacement for useState that syncs to localStorage.
   Falls back to plain useState if localStorage is unavailable. */
const useLocalStorage = (key, defaultValue) => {
  const [value, setValue] = useState(() => {
    try {
      const stored = getStorageRaw(key);
      if (stored == null) return defaultValue;
      const parsed = JSON.parse(stored);
      return parsed;
    } catch (e) {
      return defaultValue;
    }
  });

  useEffect(() => {
    try {
      if (value == null || (Array.isArray(value) && value.length === 0)) {
        // Skip storing empty initial state to save space
        return;
      }
      guardedLocalStorageSet(key, value);
    } catch (e) {
      // Quota exceeded or disabled — silently ignore
      console.warn("[useLocalStorage] save failed:", key, e.message);
    }
  }, [key, value]);

  return [value, setValue];
};

// Export all data as JSON (for manual backup)
const exportAllData = () => {
  try {
    const keys = Object.keys(window.localStorage).filter(k => k.startsWith("jamsa_"));
    const data = {};
    keys.forEach(k => { try { data[k] = JSON.parse(window.localStorage[k]); } catch(e) {} });
    const json = JSON.stringify({ version: 1, exportedAt: new Date().toISOString(), data }, null, 2);
    const blob = new Blob([json], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `jamsa-backup-${new Date().toISOString().slice(0,10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
    return true;
  } catch (e) {
    alert("백업 내보내기 실패: " + e.message);
    return false;
  }
};

// Import JSON backup
const importAllData = (file) => new Promise((resolve, reject) => {
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const parsed = JSON.parse(e.target.result);
      if (!parsed.data) throw new Error("올바른 백업 파일이 아닙니다");
      Object.entries(parsed.data).forEach(([k, v]) => {
        try { window.localStorage.setItem(k, JSON.stringify(v)); } catch(e2) {}
      });
      resolve(parsed);
    } catch (err) { reject(err); }
  };
  reader.onerror = () => reject(new Error("파일 읽기 실패"));
  reader.readAsText(file);
});

const INV_KEY = "jamsa_inv_prods";
const INV_AUTO_BACKUP_KEY = "jamsa_inv_prods_auto_backups";
const INV_EXCEL_BACKUP_PREFIX = "jamsa_inv_prods_before_excel_";

const safeJsonParse = (raw, fallback = null) => {
  try { return JSON.parse(raw); } catch (e) { return fallback; }
};

const normalizeInventoryCode = (v) => String(v || "").trim().toUpperCase();
const normalizeInventoryName = (v) => String(v || "").trim();

const makeInventorySnapshot = (items, reason = "manual") => ({
  id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
  at: new Date().toISOString(),
  reason,
  count: Array.isArray(items) ? items.length : 0,
  items: Array.isArray(items) ? items : [],
});

const saveInventoryAutoBackup = (items, reason = "auto") => {
  try {
    if (!Array.isArray(items) || items.length === 0) return false;
    const prev = safeJsonParse(window.localStorage?.getItem(INV_AUTO_BACKUP_KEY) || "[]", []);
    const last = Array.isArray(prev) ? prev[0] : null;
    const sig = items.map(p => `${p.id}:${p.code}:${p.name}:${p.qty}:${p.loc}:${p.cat}:${p.subLoc || ""}`).join("|");
    if (last?.sig === sig) return false;
    const snap = { ...makeInventorySnapshot(items, reason), sig };
    window.localStorage?.setItem(INV_AUTO_BACKUP_KEY, JSON.stringify([snap, ...(Array.isArray(prev) ? prev : [])].slice(0, 30)));
    return true;
  } catch (e) {
    console.warn("[inventory backup] failed:", e.message);
    return false;
  }
};

const decodeInventoryRestorePayload = (raw) => {
  const text = decodeURIComponent(String(raw || ""));
  if (!text.startsWith("b64:")) return safeJsonParse(text, null);
  const bytes = Uint8Array.from(atob(text.slice(4).replace(/-/g, "+").replace(/_/g, "/")), c => c.charCodeAt(0));
  return safeJsonParse(new TextDecoder().decode(bytes), null);
};

const applyInventoryHashRestore = () => {
  try {
    if (typeof window === "undefined" || !window.location?.hash) return null;
    const prefix = "#restoreInventory=";
    if (!window.location.hash.startsWith(prefix)) return null;
    const items = decodeInventoryRestorePayload(window.location.hash.slice(prefix.length));
    if (!Array.isArray(items) || items.length === 0) return null;
    const current = safeJsonParse(window.localStorage?.getItem(INV_KEY) || "[]", []);
    saveInventoryAutoBackup(current, "before-hash-restore");
    window.localStorage?.setItem(INV_KEY, JSON.stringify(items));
    window.localStorage?.setItem("jamsa_inv_recovered_at", new Date().toISOString());
    window.sessionStorage?.setItem("jamsa_inv_restore_notice", `${items.length}개 재고 복구 완료`);
    window.history?.replaceState(null, "", `${window.location.pathname}${window.location.search}`);
    return { items };
  } catch (e) {
    console.warn("[inventory restore link] failed:", e.message);
    return null;
  }
};
applyInventoryHashRestore();

const applyInventoryFileRestore = async () => {
  try {
    if (typeof window === "undefined" || !window.location?.hash) return null;
    const prefix = "#restoreInventoryFile=";
    if (!window.location.hash.startsWith(prefix)) return null;
    const url = decodeURIComponent(window.location.hash.slice(prefix.length));
    const res = await fetch(url, { cache: "no-store" });
    if (!res.ok) throw new Error(`restore file ${res.status}`);
    const items = await res.json();
    if (!Array.isArray(items) || items.length === 0) return null;
    const current = safeJsonParse(window.localStorage?.getItem(INV_KEY) || "[]", []);
    saveInventoryAutoBackup(current, "before-file-restore");
    window.localStorage?.setItem(INV_KEY, JSON.stringify(items));
    window.localStorage?.setItem("jamsa_inv_recovered_at", new Date().toISOString());
    window.sessionStorage?.setItem("jamsa_inv_restore_notice", `${items.length}개 재고 복구 완료`);
    window.history?.replaceState(null, "", `${window.location.pathname}${window.location.search}`);
    return { items };
  } catch (e) {
    console.warn("[inventory restore file] failed:", e.message);
    return null;
  }
};
applyInventoryFileRestore().then(restored => {
  if (restored?.items) setTimeout(() => window.location.reload(), 80);
});

const collectInventoryRecoveryCandidates = () => {
  const candidates = [];
  const addCandidate = (source, label, items, meta = {}) => {
    if (!Array.isArray(items) || items.length === 0) return;
    candidates.push({
      id: `${source}-${candidates.length}`,
      source,
      label,
      count: items.length,
      at: meta.at || null,
      items,
      meta,
    });
  };
  try {
    const current = safeJsonParse(window.localStorage?.getItem(INV_KEY) || "[]", []);
    addCandidate("current", "현재 브라우저 저장 재고", current, { at: "현재" });
  } catch (e) {}
  try {
    const backups = safeJsonParse(window.localStorage?.getItem(INV_AUTO_BACKUP_KEY) || "[]", []);
    (Array.isArray(backups) ? backups : []).forEach((snap, idx) => {
      addCandidate("auto", `자동 백업 ${idx + 1}`, snap.items, { at: snap.at, reason: snap.reason });
    });
  } catch (e) {}
  try {
    Object.keys(window.localStorage || {})
      .filter(k => k.startsWith(INV_EXCEL_BACKUP_PREFIX) || k.startsWith("jamsa_inv_prods_backup_"))
      .sort()
      .reverse()
      .forEach(k => {
        const data = safeJsonParse(window.localStorage.getItem(k) || "[]", []);
        const items = Array.isArray(data) ? data : data.items;
        addCandidate("named", `저장 백업: ${k.replace(/^jamsa_inv_prods_/, "")}`, items, { at: data.at || k });
      });
  } catch (e) {}
  try {
    const hist = safeJsonParse(window.localStorage?.getItem("jamsa_inv_hist") || "[]", []);
    const byName = new Map();
    (Array.isArray(hist) ? hist : []).forEach(h => {
      const name = normalizeInventoryName(h.pn || h.name || h.productName);
      if (!name) return;
      const cur = byName.get(name) || { id: byName.size + 1, name, cat: "기타", loc: "미지정", qty: 0, locs: {}, memo: "입출고 기록에서 복구 후보 생성", code: genCode(byName.size + 1), photos: [], minQty: 0, unit: "개" };
      const detail = String(h.det || "");
      const qty = Number(h.q || 0);
      const locMatch = detail.match(/^(.+?)(?:에서|에|로|:|\s)/);
      const loc = locMatch?.[1]?.trim() || cur.loc || "미지정";
      if (/추가|입고|일괄/.test(String(h.act || ""))) {
        cur.qty += qty || 0;
        cur.loc = cur.loc === "미지정" ? loc : cur.loc;
        cur.locs[loc] = (cur.locs[loc] || 0) + (qty || 0);
      } else if (/출고/.test(String(h.act || ""))) {
        cur.qty = Math.max(0, cur.qty - (qty || 0));
        cur.locs[loc] = Math.max(0, (cur.locs[loc] || 0) - (qty || 0));
      } else if (/조정/.test(String(h.act || "")) && qty >= 0) {
        cur.qty = qty;
        cur.locs[loc] = qty;
      }
      byName.set(name, cur);
    });
    const reconstructed = Array.from(byName.values()).map((p, idx) => ({ ...p, id: idx + 1, code: p.code || genCode(idx + 1) }));
    addCandidate("history", "입출고 기록 기반 복구 후보", reconstructed, { at: "기록 재구성", caution: "수량은 기록 문구 기반 추정입니다." });
  } catch (e) {}
  return candidates.sort((a, b) => (b.count || 0) - (a.count || 0));
};

const getFieldValue = (row, aliases) => {
  const entries = Object.entries(row || {});
  for (const alias of aliases) {
    const found = entries.find(([k]) => String(k).trim().toLowerCase() === alias.toLowerCase());
    if (found) return found[1];
  }
  for (const alias of aliases) {
    const found = entries.find(([k]) => String(k).replace(/\s/g, "").toLowerCase().includes(alias.replace(/\s/g, "").toLowerCase()));
    if (found) return found[1];
  }
  return "";
};

const normalizeInventoryImportRow = (row, defaults = {}) => {
  const code = normalizeInventoryCode(getFieldValue(row, ["QR코드", "QR", "code", "상품코드", "제품코드"]));
  const name = normalizeInventoryName(getFieldValue(row, ["제품명", "품목", "품목명", "name", "상품명"]));
  if (!name && !code) return null;
  const qtyRaw = getFieldValue(row, ["수량", "재고", "qty", "quantity", "현재수량"]);
  const minRaw = getFieldValue(row, ["적정재고", "최소수량", "minQty", "min", "안전재고"]);
  const cat = normalizeInventoryName(getFieldValue(row, ["카테고리", "분류", "category", "cat"])) || defaults.cat || "기타";
  const loc = normalizeInventoryName(getFieldValue(row, ["위치", "장소", "location", "loc", "구역"])) || defaults.loc || "미지정";
  const subLoc = normalizeInventoryName(getFieldValue(row, ["세부위치", "선반", "칸", "상세위치", "subLoc", "detailLocation"]));
  return {
    code,
    name,
    cat,
    loc,
    subLoc,
    qty: qtyRaw === "" || qtyRaw == null ? null : Math.max(0, Number(String(qtyRaw).replace(/[^0-9.-]/g, "")) || 0),
    minQty: minRaw === "" || minRaw == null ? undefined : Math.max(0, Number(String(minRaw).replace(/[^0-9.-]/g, "")) || 0),
    unit: normalizeInventoryName(getFieldValue(row, ["단위", "unit"])) || "개",
    memo: normalizeInventoryName(getFieldValue(row, ["메모", "비고", "memo", "특이사항"])),
  };
};

// CSV/\uC5D1\uC140 \uC778\uCF54\uB529 \uC790\uB3D9 \uAC10\uC9C0 \u2014 UTF-8 \uC6B0\uC120, \uC2E4\uD328 \uC2DC EUC-KR/CP949 \uD3F4\uBC31
// Windows \uC5D1\uC140\uC5D0\uC11C "CSV(\uC27C\uD45C\uB85C \uBD84\uB9AC)" \uC800\uC7A5\uD558\uBA74 \uAC70\uC758 EUC-KR (\uD55C\uAE00 \uAE68\uC9D0 \uBC29\uC9C0\uC6A9)
const decodeBytesAsText = (buf) => {
  // 1\uCC28: UTF-8 strict \u2014 \uD55C\uAE00\uC774 \uC798\uBABB\uB41C \uC704\uCE58\uC5D0 \uC788\uC73C\uBA74 throw
  try {
    const utf8 = new TextDecoder("utf-8", { fatal: true }).decode(buf);
    return utf8;
  } catch (e) { /* fallback */ }
  // 2\uCC28: EUC-KR (Windows-949 \uB3D9\uB4F1) \u2014 \uD55C\uAD6D \uC708\uB3C4\uC6B0 \uC5D1\uC140 \uAE30\uBCF8
  try { return new TextDecoder("euc-kr", { fatal: false }).decode(buf); }
  catch (e) { /* try cp949 */ }
  try { return new TextDecoder("cp949", { fatal: false }).decode(buf); }
  catch (e) { /* final fallback */ }
  // 3\uCC28: UTF-8 lenient (\uFFFD \uCE58\uD658 \uD5C8\uC6A9)
  return new TextDecoder("utf-8", { fatal: false }).decode(buf);
};

const parseInventorySpreadsheet = async (file) => {
  const ext = file.name.split(".").pop()?.toLowerCase();
  if (ext === "csv") {
    const buf = await file.arrayBuffer();
    const text = decodeBytesAsText(buf).replace(/^\uFEFF/, "");
    const lines = text.split(/\r?\n/).filter(Boolean);
    const rows = lines.map(line => line.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/).map(v => v.replace(/^"|"$/g, "").replace(/""/g, '"').trim()));
    const headers = rows.shift() || [];
    return rows.map(cols => Object.fromEntries(headers.map((h, i) => [h, cols[i] ?? ""])));
  }
  const XLSX = await loadXLSX();
  const buf = await file.arrayBuffer();
  // .xls(\uAD6C\uBC84\uC804)\uB3C4 codepage \uC790\uB3D9 \uAC10\uC9C0
  const wb = XLSX.read(buf, { type: "array", cellDates: false, raw: false, codepage: 949 });
  const ws = wb.Sheets[wb.SheetNames[0]];
  return XLSX.utils.sheet_to_json(ws, { defval: "", raw: false });
};

