/* ==================== Phase 3 — 동의 / 정정 요청 모달 ====================
   설계 §3.2, §3.4, §6.1. 직원이 본인 입장에서 사용. admin은 별도 검토 UI 사용.
*/
const CONSENT_TEXT_V32_LINES = [
  "수집 항목: GPS 좌표, BLE 신호, 디바이스 ID",
  "수집 목적: 출퇴근 자동 인식, 근무지 이탈 방지, 비상 안전",
  "수집 시간: 근무 시작 1시간 전 ~ 종료 30분 후",
  "보유 기간: 원본 90일 / 집계 3년",
  "제3자 제공: 없음 (고객사에는 익명화 후)",
  "동의 거부 시 불이익: 없음 (수동 출근 대체)",
];
const CONSENT_SCOPE_OPTIONS = [
  { key: "gps",              label: "GPS 좌표 수집" },
  { key: "ble",              label: "BLE 비콘 신호 수집" },
  { key: "work_hours_only",  label: "근무 시간대만 (외 시간 미수집)" },
];

function getAuthToken() {
  try {
    return window.__authToken
      || window.localStorage?.getItem("__supabase_token")
      || "";
  } catch (e) { return ""; }
}

function ConsentModal({ onClose, onAgreed }) {
  const [scope, setScope] = useState(["gps", "ble", "work_hours_only"]);
  const [agreed, setAgreed] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const toggle = (key) => setScope(prev => prev.includes(key) ? prev.filter(k => k !== key) : [...prev, key]);

  async function submit() {
    if (!agreed) { setError("동의 체크박스를 선택해주세요"); return; }
    if (scope.length === 0) { setError("최소 1개 수집 범위는 동의해야 합니다"); return; }
    setSubmitting(true); setError("");
    try {
      const r = await fetch("/api/consent", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${getAuthToken()}` },
        body: JSON.stringify({ scope }),
      });
      const j = await r.json();
      if (!r.ok || !j.ok) {
        if (j.error === "consent_already_active") {
          onAgreed?.({ alreadyActive: true });
          onClose();
          return;
        }
        setError(j.error || "동의 등록 실패");
        return;
      }
      onAgreed?.(j);
      onClose();
    } catch (e) { setError("네트워크 오류: " + e.message); }
    finally { setSubmitting(false); }
  }

  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, zIndex: 10095, background: "rgba(15,23,42,0.65)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}>
      <div onClick={e => e.stopPropagation()} style={{ background: "#fff", borderRadius: 12, width: 540, maxWidth: "95vw", maxHeight: "90vh", overflow: "auto", padding: 24 }}>
        <div style={{ fontSize: 17, fontWeight: 800, marginBottom: 4 }}>📜 위치정보 수집·이용 동의 (v3.2)</div>
        <div style={{ fontSize: 11.5, color: "#64748b", marginBottom: 14 }}>위치정보법 제18조 · 한국잠사플레이팜 통합관리 시스템</div>

        <div style={{ background: "#f8fafc", border: "1px solid #e2e8f0", borderRadius: 8, padding: 14, marginBottom: 14, fontSize: 12.5, lineHeight: 1.75 }}>
          {CONSENT_TEXT_V32_LINES.map((line, i) => <div key={i}>• {line}</div>)}
        </div>

        <div style={{ fontSize: 12, fontWeight: 700, color: "#475569", marginBottom: 8 }}>수집 범위 선택 (직원이 직접 선택 가능)</div>
        {CONSENT_SCOPE_OPTIONS.map(o => (
          <label key={o.key} style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 4px", fontSize: 12.5, cursor: "pointer" }}>
            <input type="checkbox" checked={scope.includes(o.key)} onChange={() => toggle(o.key)} />
            {o.label}
          </label>
        ))}

        <label style={{ display: "flex", alignItems: "center", gap: 8, padding: "12px 4px 4px", fontSize: 13, fontWeight: 700, cursor: "pointer", borderTop: "1px solid #e2e8f0", marginTop: 12 }}>
          <input type="checkbox" checked={agreed} onChange={e => setAgreed(e.target.checked)} />
          위 내용을 모두 확인하였으며, 위치정보 수집·이용에 동의합니다.
        </label>

        {error && (
          <div style={{ background: "#fef2f2", border: "1px solid #fecaca", borderRadius: 6, padding: "8px 12px", margin: "10px 0", fontSize: 11.5, color: "#b91c1c" }}>❌ {error}</div>
        )}

        <div style={{ display: "flex", gap: 8, justifyContent: "flex-end", marginTop: 14 }}>
          <button onClick={onClose} style={{ padding: "9px 16px", borderRadius: 6, border: "1px solid #e2e8f0", background: "#fff", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>나중에</button>
          <button onClick={submit} disabled={!agreed || submitting}
            style={{ padding: "9px 18px", borderRadius: 6, border: "none", background: agreed ? "linear-gradient(135deg,#16a34a,#15803d)" : "#cbd5e1", color: "#fff", fontSize: 12, fontWeight: 700, cursor: agreed ? "pointer" : "not-allowed" }}>
            {submitting ? "등록 중..." : "동의 등록"}
          </button>
        </div>
        <div style={{ fontSize: 10.5, color: "#94a3b8", marginTop: 10, lineHeight: 1.55 }}>
          ※ 동의 후에도 언제든 직원 화면에서 철회 가능합니다. 철회 시 GPS·BLE 수집이 즉시 중단되며, 수동 출근으로 대체됩니다.
        </div>
      </div>
    </div>
  );
}

function CorrectionRequestModal({ onClose, onSubmitted }) {
  const [date, setDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [field, setField] = useState("check_in");
  const [valueBefore, setValueBefore] = useState("");
  const [valueAfter, setValueAfter] = useState("");
  const [reason, setReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const reasonOk = reason.trim().length >= 10;

  async function submit() {
    if (!valueAfter) { setError("정정 후 시각을 입력해주세요"); return; }
    if (!reasonOk) { setError("사유를 10자 이상 입력해주세요"); return; }
    setSubmitting(true); setError("");
    try {
      const r = await fetch("/api/correction", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${getAuthToken()}` },
        body: JSON.stringify({ date, field, valueBefore: valueBefore || null, valueAfter, reason: reason.trim() }),
      });
      const j = await r.json();
      if (!r.ok || !j.ok) { setError(j.error || "요청 실패"); return; }
      onSubmitted?.(j);
      onClose();
    } catch (e) { setError("네트워크 오류: " + e.message); }
    finally { setSubmitting(false); }
  }

  const labelStyle = { display: "block", fontSize: 11, fontWeight: 700, marginBottom: 4, color: "#475569" };
  const inputStyle = { width: "100%", padding: "8px 10px", border: "1px solid #e2e8f0", borderRadius: 6, fontSize: 12.5, marginBottom: 10, fontFamily: "inherit" };

  return (
    <div onClick={onClose} style={{ position: "fixed", inset: 0, zIndex: 10095, background: "rgba(15,23,42,0.6)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}>
      <div onClick={e => e.stopPropagation()} style={{ background: "#fff", borderRadius: 12, width: 480, maxWidth: "95vw", maxHeight: "90vh", overflow: "auto", padding: 22 }}>
        <div style={{ fontSize: 16, fontWeight: 800, marginBottom: 6 }}>📝 출퇴근 정정 요청</div>
        <div style={{ fontSize: 11.5, color: "#64748b", marginBottom: 14, lineHeight: 1.55 }}>
          관리자 승인 후 반영됩니다. 사유는 영구 보존되며 노무사 감사 대상입니다 (근로기준법 §42).
        </div>

        <label style={labelStyle}>일자</label>
        <input type="date" value={date} onChange={e => setDate(e.target.value)} style={inputStyle} />

        <label style={labelStyle}>항목</label>
        <select value={field} onChange={e => setField(e.target.value)} style={inputStyle}>
          <option value="check_in">출근시각</option>
          <option value="check_out">퇴근시각</option>
          <option value="break_time">휴게 시작</option>
        </select>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
          <div>
            <label style={labelStyle}>기존 기록 (선택)</label>
            <input type="time" value={valueBefore} onChange={e => setValueBefore(e.target.value)} style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>정정 후 시각</label>
            <input type="time" value={valueAfter} onChange={e => setValueAfter(e.target.value)} style={inputStyle} />
          </div>
        </div>

        <label style={labelStyle}>사유 (10자 이상) <span style={{ float: "right", color: reasonOk ? "#16a34a" : "#dc2626", fontWeight: 700 }}>{reason.trim().length} / 10</span></label>
        <textarea value={reason} onChange={e => setReason(e.target.value)}
          placeholder="예: BLE 인식 지연으로 출근 시각이 잘못 기록됨. 실제 도착 시각은 08:55."
          style={{ ...inputStyle, minHeight: 70, resize: "vertical" }} />

        {error && (
          <div style={{ background: "#fef2f2", border: "1px solid #fecaca", borderRadius: 6, padding: "8px 12px", marginBottom: 10, fontSize: 11.5, color: "#b91c1c" }}>❌ {error}</div>
        )}

        <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
          <button onClick={onClose} style={{ padding: "9px 16px", borderRadius: 6, border: "1px solid #e2e8f0", background: "#fff", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>취소</button>
          <button onClick={submit} disabled={!reasonOk || !valueAfter || submitting}
            style={{ padding: "9px 18px", borderRadius: 6, border: "none", background: (reasonOk && valueAfter) ? "linear-gradient(135deg,#3b82f6,#2563eb)" : "#cbd5e1", color: "#fff", fontSize: 12, fontWeight: 700, cursor: (reasonOk && valueAfter) ? "pointer" : "not-allowed" }}>
            {submitting ? "요청 중..." : "정정 요청"}
          </button>
        </div>
      </div>
    </div>
  );
}

/* ==================== Phase 2 — 정밀 위치 사유 입력 모달 ====================
   설계 §5.3, §11.1. admin만 사용 가능, lawyer는 사후 로그 조회만.
   서버에 reason_detail 50자 이상 + legal_basis 전송, 로그 INSERT 후 좌표 반환.
*/
const PRECISE_REASON_CATEGORIES = [
  { key: "BLE_DEBUG",      label: "BLE 미수신 원인 확인" },
  { key: "EMERGENCY",      label: "긴급 안전 사고 대응" },
  { key: "PAYROLL_VERIFY", label: "출퇴근 기록 정정 검증" },
  { key: "CUSTOMER_ISSUE", label: "고객 응대 필요" },
  { key: "OTHER",          label: "기타" },
];
const LEGAL_BASIS_OPTIONS = [
  "위치정보법 제16조 (관리적 보호조치)",
  "근로기준법 제43조 (임금대장)",
  "고용계약상 안전관리 의무",
  "고객 서비스 이행",
];

function PreciseLocationModal({ targetUser, onClose, onSuccess, currentUser }) {
  const [reasonCat, setReasonCat] = useState(PRECISE_REASON_CATEGORIES[0].key);
  const [reasonDetail, setReasonDetail] = useState("");
  const [legalBasis, setLegalBasis] = useState(LEGAL_BASIS_OPTIONS[0]);
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState("");
  const detailLen = reasonDetail.trim().length;
  const detailOk = detailLen >= 50;
  const role6 = normalizeRole6(currentUser?.role);
  const canSubmit = role6 === "admin" && detailOk && !submitting;

  async function submit() {
    setSubmitting(true); setError("");
    try {
      const token = window.__authToken || window.localStorage?.getItem("__supabase_token") || "";
      const r = await fetch("/api/precise-location", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify({
          targetStaffId: targetUser?.id,
          targetAnon: targetUser?.anon || null,
          reasonCategory: reasonCat,
          reasonDetail: reasonDetail.trim(),
          legalBasis,
        }),
      });
      const j = await r.json();
      if (!r.ok || !j.ok) {
        setError(j.error === "reason_too_short" ? "사유 50자 이상 필요"
          : j.error === "forbidden" ? "권한 없음 (admin 필요)"
          : j.error === "missing_token" || j.error === "invalid_token" ? "로그인 필요 — 세션 만료됨"
          : j.error || "요청 실패");
        return;
      }
      setResult(j);
      onSuccess?.(j);
    } catch (e) {
      setError("네트워크 오류: " + e.message);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div onClick={onClose}
      style={{ position: "fixed", inset: 0, zIndex: 10090, background: "rgba(15,23,42,0.6)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}>
      <div onClick={e => e.stopPropagation()}
        style={{ background: "#fff", borderRadius: 12, width: 500, maxWidth: "95vw", maxHeight: "90vh", overflow: "auto", padding: 22, boxShadow: "0 20px 60px rgba(0,0,0,0.4)" }}>
        <div style={{ fontSize: 16, fontWeight: 800, marginBottom: 6 }}>🔍 정밀 위치 열람 요청</div>
        <div style={{ fontSize: 12, color: "#64748b", marginBottom: 14, lineHeight: 1.6 }}>
          대상: <strong>{targetUser?.name || targetUser?.id}</strong>
          {targetUser?.anon && <span style={{ marginLeft: 4, padding: "1px 6px", borderRadius: 4, background: "#f1f5f9", fontWeight: 700 }}>{targetUser.anon}</span>}
          <br />이 작업은 <strong>위치정보법 제16조</strong>에 따라 사유 입력이 필수이며, 모든 접근은 영구 로그에 기록됩니다.
        </div>

        {result ? (
          <div style={{ background: "#ecfdf5", border: "1px solid #a7f3d0", borderRadius: 8, padding: 14 }}>
            <div style={{ fontSize: 13, fontWeight: 800, color: "#065f46", marginBottom: 8 }}>✓ 사유 기록됨 · 좌표 반환</div>
            <div style={{ fontSize: 12, color: "#047857", lineHeight: 1.7 }}>
              📍 <strong>{result.location?.lat?.toFixed(6)}, {result.location?.lng?.toFixed(6)}</strong><br />
              정확도 ±{Math.round(result.location?.accuracy || 0)}m · {result.location?.source || "?"}<br />
              마지막 업데이트: {result.location?.updatedAt ? new Date(result.location.updatedAt).toLocaleString("ko-KR") : "-"}<br />
              <span style={{ fontSize: 11, color: "#64748b", marginTop: 6, display: "block" }}>접근 로그 ID: {result.accessLogId}</span>
            </div>
            <button onClick={onClose}
              style={{ marginTop: 12, padding: "8px 14px", borderRadius: 6, border: "none", background: "#0f172a", color: "#fff", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>
              닫기
            </button>
          </div>
        ) : (
          <>
            {role6 !== "admin" && (
              <div style={{ background: "#fef3c7", border: "1px solid #fcd34d", borderRadius: 6, padding: "8px 12px", marginBottom: 12, fontSize: 11.5, color: "#92400e" }}>
                ⚠️ 정밀 위치 열람은 관리자(admin)만 가능합니다. 현재 역할: <strong>{role6}</strong>
              </div>
            )}
            <label style={{ display: "block", fontSize: 11, fontWeight: 700, marginBottom: 4, color: "#475569" }}>열람 사유 (필수)</label>
            <select value={reasonCat} onChange={e => setReasonCat(e.target.value)}
              style={{ width: "100%", padding: "8px 10px", border: "1px solid #e2e8f0", borderRadius: 6, fontSize: 12.5, marginBottom: 10 }}>
              {PRECISE_REASON_CATEGORIES.map(c => <option key={c.key} value={c.key}>{c.label}</option>)}
            </select>

            <label style={{ display: "block", fontSize: 11, fontWeight: 700, marginBottom: 4, color: "#475569" }}>
              상세 설명 (50자 이상) <span style={{ float: "right", color: detailOk ? "#16a34a" : "#dc2626", fontWeight: 700 }}>{detailLen} / 50</span>
            </label>
            <textarea value={reasonDetail} onChange={e => setReasonDetail(e.target.value)}
              placeholder="예: 14:32 BLE 게이트웨이 신호가 끊긴 시점부터 현장 위치 확인 필요. 고객 응대 중 사고 대응 가능성."
              style={{ width: "100%", padding: "8px 10px", border: `1px solid ${detailOk ? "#a7f3d0" : "#e2e8f0"}`, borderRadius: 6, fontSize: 12.5, minHeight: 80, resize: "vertical", marginBottom: 10, fontFamily: "inherit" }} />

            <label style={{ display: "block", fontSize: 11, fontWeight: 700, marginBottom: 4, color: "#475569" }}>법적 근거</label>
            <select value={legalBasis} onChange={e => setLegalBasis(e.target.value)}
              style={{ width: "100%", padding: "8px 10px", border: "1px solid #e2e8f0", borderRadius: 6, fontSize: 12.5, marginBottom: 12 }}>
              {LEGAL_BASIS_OPTIONS.map(o => <option key={o}>{o}</option>)}
            </select>

            {error && (
              <div style={{ background: "#fef2f2", border: "1px solid #fecaca", borderRadius: 6, padding: "8px 12px", marginBottom: 12, fontSize: 11.5, color: "#b91c1c" }}>
                ❌ {error}
              </div>
            )}

            <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
              <button onClick={onClose}
                style={{ padding: "9px 16px", borderRadius: 6, border: "1px solid #e2e8f0", background: "#fff", fontSize: 12, fontWeight: 700, cursor: "pointer" }}>
                취소
              </button>
              <button onClick={submit} disabled={!canSubmit}
                style={{ padding: "9px 16px", borderRadius: 6, border: "none", background: canSubmit ? "linear-gradient(135deg,#dc2626,#b91c1c)" : "#cbd5e1", color: "#fff", fontSize: 12, fontWeight: 700, cursor: canSubmit ? "pointer" : "not-allowed" }}>
                {submitting ? "기록 중..." : "사유 기록 + 열람"}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

/* ==================== Phase 1 — 역할별 전용 화면 ====================
   설계 문서 §11 참고. 데이터는 시연용 mock — Phase 3에서 Supabase
   consent_records / location_access_log / service_sessions로 교체.
*/

function RoleBanner({ roleKey, title, sub }) {
  const meta = ROLE6_META[roleKey] || ROLE6_META.staff;
  return (
    <div style={{ display: "flex", gap: 14, alignItems: "center", padding: "18px 22px",
      background: `linear-gradient(135deg, ${meta.color}, ${meta.color}cc)`,
      color: "#fff", borderRadius: 12, marginBottom: 16, boxShadow: "0 4px 14px rgba(0,0,0,0.08)" }}>
      <div style={{ fontSize: 34 }}>{meta.emoji}</div>
      <div>
        <div style={{ fontSize: 18, fontWeight: 800, marginBottom: 4 }}>{title}</div>
        <div style={{ fontSize: 12.5, opacity: 0.92, lineHeight: 1.5 }}>{sub}</div>
      </div>
    </div>
  );
}

function CeoStat({ label, value, unit, tone = "neutral", note }) {
  const colors = {
    good:    { bg: "#ecfdf5", border: "#a7f3d0", text: "#047857" },
    warn:    { bg: "#fef3c7", border: "#fcd34d", text: "#92400e" },
    neutral: { bg: "#f8fafc", border: "#e2e8f0", text: "#0f172a" },
  };
  const c = colors[tone];
  return (
    <div style={{ background: c.bg, border: `1px solid ${c.border}`, borderRadius: 10, padding: "14px 16px" }}>
      <div style={{ fontSize: 11, fontWeight: 700, color: "#64748b", marginBottom: 6 }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 900, color: c.text, lineHeight: 1 }}>
        {value}{unit && <span style={{ fontSize: 13, fontWeight: 700, marginLeft: 3 }}>{unit}</span>}
      </div>
      {note && <div style={{ fontSize: 11, color: "#64748b", marginTop: 6 }}>{note}</div>}
    </div>
  );
}

